f"'),1,20)='repository_bindings:' AND json_extract(sv.value,'$.column')='repository_binding_id')) WHEN 'kind' THEN NOT (0) WHEN 'locked' THEN NOT (0) WHEN 'merge_oid' THEN NOT (((SELECT count(*) FROM json_each(sv.value))=1 AND json_type(sv.value,'$."$bytes"')='text') OR ((SELECT count(*) FROM json_each(sv.value))=1 AND json_type(sv.value,'$."$sha256"')='text' AND length(json_extract(sv.value,'$."$sha256"'))=64 AND json_extract(sv.value,'$."$sha256"') NOT GLOB '*[^0-9a-f]*')) WHEN 'merged' THEN NOT (0) WHEN 'merged_at_us' THEN NOT (0) WHEN 'metadata' THEN NOT (0) WHEN 'object_format' THEN NOT (0) WHEN 'observed_at_us' THEN NOT (0) WHEN 'parsed_at_us' THEN NOT (0) WHEN 'parser_module' THEN NOT (0) WHEN 'parser_version' THEN NOT (0) WHEN 'provider_clock_scope' THEN NOT (0) WHEN 'provider_resource_id' THEN NOT (0) WHEN 'provider_updated_at_us' THEN NOT (0) WHEN 'repository_binding_id' THEN NOT (((SELECT count(*) FROM json_each(sv.value))=2 AND json_type(sv.value,'$."$ref"')='text' AND substr(json_extract(sv.value,'$."$ref"'),1,20)='repository_bindings:' AND json_extract(sv.value,'$.column')='repository_binding_id')) WHEN 'repository_uuidv4' THEN NOT (((SELECT count(*) FROM json_each(sv.value))=2 AND json_type(sv.value,'$."$ref"')='text' AND substr(json_extract(sv.value,'$."$ref"'),1,16)='change_requests:' AND json_extract(sv.value,'$.column')='repository_uuidv4') OR ((SELECT count(*) FROM json_each(sv.value))=2 AND json_type(sv.value,'$."$ref"')='text' AND substr(json_extract(sv.value,'$."$ref"'),1,20)='repository_bindings:' AND json_extract(sv.value,'$.column')='repository_uuidv4') OR ((SELECT count(*) FROM json_each(sv.value))=2 AND json_type(sv.value,'$."$ref"')='text' AND substr(json_extract(sv.value,'$."$ref"'),1,13)='repositories:' AND json_extract(sv.value,'$.column')='repository_uuidv4')) WHEN 'service_instance_uuidv4' THEN NOT (((SELECT count(*) FROM json_each(sv.value))=2 AND json_type(sv.value,'$."$ref"')='text' AND substr(json_extract(sv.value,'$."$ref"'),1,